// 1. Získáme ID toho, kdo akci provedl
const actorId = $('Code in JavaScript').item.json.body.activity.actor.id;

// 2. Získáme seznam přiřazených lidí
const assignees = $input.item.json.assignees || [];

// 3. FILTR & DEDUPLIKACE
// Použijeme "Set" pro sledování už unikátních ID, abychom neposlali zprávu 2x stejnému člověku
const uniqueRecipients = [];
const seenIds = new Set();

for (const user of assignees) {
  // Podmínka: Uživatel NENÍ autor A ZÁROVEŇ jsme ho ještě nepřidali do seznamu
  if (user.id !== actorId && !seenIds.has(user.id)) {
    seenIds.add(user.id);
    uniqueRecipients.push(user);
  }
}

// 4. Pokud nikdo nezbyl, zastavíme to
if (uniqueRecipients.length === 0) {
  return [];
}

// 5. Vrátíme čistý seznam
return uniqueRecipients.map(user => ({ json: user }));

