// 2. FUNKCE: PŘEVOD HTML NA ČISTÝ TEXT (Pro Google Sheets)
function htmlToText(html) {
  if (!html) return "";
  let text = String(html)
    .replace(/<\/td>/gi, '   ')      
    .replace(/<\/tr>/gi, '\n')       
    .replace(/<\/p>/gi, '\n')        
    .replace(/<\/div>/gi, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/h[1-6]>/gi, '\n\n')
    .replace(/<li[^>]*>/gi, '• ')
    .replace(/<\/li>/gi, '\n')
    .replace(/<[^>]+>/g, '')         
    .replace(/&nbsp;/g, ' ');

  return text.replace(/\n\s*\n\s*\n/g, '\n\n').trim();
}

// Plný text pro Excel (zachová vše, jen odstraní HTML)
const fullText = htmlToText(rawInput);


// 3. FUNKCE: FILTROVÁNÍ PRO KALENDÁŘ (Zkrácená verze)
function filterImportantInfo(text) {
  if (!text) return "";
  let result = "";

  // Kontakt
  const startKontakt = text.indexOf("Kontaktní osoba");
  const startInfo = text.indexOf("Info z Peakforce");
  if (startKontakt !== -1) {
    const endKontakt = (startInfo !== -1) ? startInfo : text.length;
    result += text.substring(startKontakt, endKontakt).trim() + "\n\n"; 
  }

  // Skenování
  const startSken = text.indexOf("Skenování");
  const startPost = text.indexOf("Postprodukce");
  if (startSken !== -1) {
    const endSken = (startPost !== -1) ? startPost : text.length;
    let sekce = text.substring(startSken, endSken).trim();
    let lines = sekce.split('\n');
    let filteredLines = [];
    filteredLines.push(lines[0]); // Nadpis
    for (let i = 1; i < lines.length; i++) {
        if (lines[i].toLowerCase().includes("datum a čas")) {
            filteredLines.push(lines[i]);
        }
    }
    if (filteredLines.length > 1) result += filteredLines.join('\n');
    else result += sekce;
  }

  if (result.trim() === "") return text;
  return result.trim();
}

const descriptionShort = filterImportantInfo(fullText);

