    stateName = currentStateId || "Stav nenalezen";
}

// 3. Příprava výstupu
// Musíme zachovat strukturu, na kterou jsou zvyklé další uzly
// Vracíme kombinaci původních dat z webhooku + opravený stav
const outputData = webhookData.data || {};

if (!outputData.state) { outputData.state = {}; }
outputData.state.name = stateName;

// Aktualizujeme i target_date, kdyby se změnil a webhook to ještě nevěděl
if (apiData.target_date) {
    outputData.target_date = apiData.target_date;
}

return {
