// Pokud ne → někdo zapsal po nás, přeskočíme

const myTs = $('Vygeneruj timestamp1').first().json.my_slack_ts;
const sheetsTs = $input.item.json.Last_Slack_Sent;

const isLatest = (myTs === sheetsTs);

