// 1. Získáme ID aktuálního běhu (to jsem já)
const myId = $execution.id;

// 2. Získáme seznam VŠECH exekucí
const allExecutions = $('Check Running Executions1').all().map(item => item.json);

// 3. FILTRUJEME jen ty SKUTEČNĚ živé
// Oprava: Musíme vyloučit stavy 'error', 'canceled', 'crashed', i když mají finished: false
let activeExecutions = allExecutions.filter(exe => 
  exe.mode !== 'manual' &&              // Ignorovat manuální testy
  exe.finished === false &&             // Musí být nedokončené
  exe.status !== 'error' &&             // NESMÍ být chyba
  exe.status !== 'canceled' &&          // NESMÍ být zrušeno
  exe.status !== 'crashed'              // NESMÍ být spadlé
);

// POJISTKA: Pokud jsi v seznamu nebyl nalezen (třeba jsi manual), přidáme tě.
const amIInList = activeExecutions.find(e => e.id === myId);
if (!amIInList && $execution.mode !== 'manual') {
    activeExecutions.push({ id: myId });
}

// 4. Seřadíme je podle ID (od nejmenšího = nejstaršího)
activeExecutions.sort((a, b) => parseInt(a.id) - parseInt(b.id));

// 5. Pokud seznam prázdný, pusť dál
if (activeExecutions.length === 0) {
     return { json: { proceed: true } };
}

// 6. Kdo je první na řadě?
const oldestId = activeExecutions[0].id;

// 7. Rozhodnutí
if (String(myId) === String(oldestId)) {
  return { json: { proceed: true } }; // Jdi
} else {
  return { json: { proceed: false } }; // Čekej
}

// ========= NASTAVENÍ =========
const BLOCK_MINUTES = 3; // Jak dlouho (v minutách) neposílat další zprávu
// =============================

// Získání ID úkolu
// Ujisti se, že název uzlu 'Code in JavaScript' přesně sedí
const taskId = $('Code in JavaScript').first().json.body.data.id;

// Přístup k trvalé paměti workflow (funguje jen v produkci/active módu!)
// OPRAVA: Přidán znak $ před název funkce
const staticData = $getWorkflowStaticData('global');

// Načteme historii, nebo vytvoříme novou
if (!staticData.lastSent) {
    staticData.lastSent = {};
}
const lastSentMap = staticData.lastSent;

const now = new Date().getTime();
const blockTimeMs = BLOCK_MINUTES * 60 * 1000;

let shouldSend = true;

// KONTROLA: Pokud už jsme tento úkol nedávno poslali
if (lastSentMap[taskId]) {
    const lastTime = new Date(lastSentMap[taskId]).getTime();
    // A zároveň uběhlo méně času než limit
    if (now - lastTime < blockTimeMs) {
        shouldSend = false;
    }
}

// ZÁPIS: Pokud se rozhodneme poslat, uložíme si čas
if (shouldSend) {
    lastSentMap[taskId] = new Date().toISOString();
}

// ČIŠTĚNÍ PAMĚTI (Aby se nezahltila starými úkoly)
// Smažeme záznamy starší než 24 hodin
const oneDay = 24 * 60 * 60 * 1000;
for (const id in lastSentMap) {
    if (now - new Date(lastSentMap[id]).getTime() > oneDay) {
        delete lastSentMap[id];
    }
}

// Vrátíme výsledek dál
return {
    json: {
        ...$input.item.json,
        shouldSend: shouldSend
    }
}
